toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 8px 16px;
    border-radius: 6px;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #f8fafc;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1e293b;
}

.timestamp {
    font-size: 0.75rem;
    color: #94a3b8;
}

.message-content {
    font-size: 0.9rem;
    color: #334155;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    background-color: #f1f5f9;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    cursor: pointer;
    transition: background-color 0.1s;
}

.reaction-badge:hover {
    background-color: #e2e8f0;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 0;
    font-size: 0.8rem;
    color: #3b82f6;
    background: none;
    border: none;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 16px;
    display: flex;
    gap: 2px;
    background-color: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    font-size: 1rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.action-btn:hover {
    background-color: #f1f5f9;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 80px;
    display: flex;
    gap: 2px;
    background-color: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 6px;
    font-size: 1.2rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.emoji-option:hover {
    background-color: #f1f5f9;
}

