{"file_text": "let observer = null;

export function observeScrollTop(sentinel, dotNetRef) {
    if (observer) {
        observer.disconnect();
    }
    observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    }, { threshold: 0.1 });
    observer.observe(sentinel);
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}
