    padding: 12px 16px;
    border-bottom: 1px solid #e2e8f0;
    flex-shrink: 0;
}

.thread-header h5 {
    margin: 0;
    font-size: 1.1rem;
    color: #1e293b;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    color: #64748b;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.close-btn:hover {
    background-color: #f1f5f9;
    color: #1e293b;
}

.thread-root {
    padding: 12px 16px;
    background-color: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1e293b;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.9rem;
    color: #334155;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.78rem;
    color: #64748b;
    border-bottom: 1px solid #e2e8f0;
    flex-shrink: 0;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1e293b;
}

.reply-time {
    font-size: 0.72rem;
    color: #94a3b8;
}

.reply-content {
    font-size: 0.85rem;
    color: #334155;
    white-space: pre-wrap;
    word-break: break-word;
}

